rm(list=ls())
wd <- 'path/to/spi/analysis' # modify for your own directory structure
setwd(wd)
# imports

library(data.table)
library(tidyverse)
library(pheatmap)

#### overall SPI ####
spitab <- 'SPI_locus.tab' # aggregated output of bedtools coverage for SPI loci. both moderns and ancients
spi_overall <- fread(spitab, header=F)
colnames(spi_overall) <- c("chr","start","end","gene","n_reads_overlap","n_bases_overlap",
                           "length","pc_covered","sample_id")
covtab <- 'mean_coverage_CT18.txt' # mean coverage from alignment to typhi CT18
cov <- fread(covtab, header=F)
colnames(cov) <- c("sample_id","cov")
spi_overall <- merge(spi_overall, cov, all.x=TRUE)
spi_overall[is.na(cov)]$cov <- 100 #if you don't have coverage data for modern genomes just set to 100
# filter for cov ≥3X; remove false positives
filt3x <- spi_overall %>% filter(cov >3) 
filt3xmat <- reshape2::acast(filt3x, sample_id ~ gene, value.var = 'pc_covered')

spi_ord <- c("SPI-1","SPI-2","SPI-3","SPI-4","SPI-5","SPI-6","SPI-7","SPI-8","SPI-9","SPI-10")

id_ord_ptc <- c("Schwarzengrund-CVM19633","BareillyCFSAN000189","Bovismorbificans3114",
                "EnteritidisP125109","GRY004",
                'SME005','SJL020','SJL019','IV3002','IKI003','BOY008',
                'S1L002','HGC040','HGC004','KKN099','AKY001','KPI001','GRY001','H1I004',
                'MAJ022','SUA004','KO1037','SAP004','HO1003','NEP019','NEP021','NEP018',
                'CHL003','XBQM20','KNC181','KNC056','KNC095','KNC041','BPN005','XBQM90',
                'CPA002','SIA006','TBS012','ETR001','BRC034','BRC017',
                'MGL011','CholeraesuisSC-B67','KNC139',
                'TGP001','KSZ005','KNL026','MGL008','HDL004',
                'GTH003','TAV007','KNL019','Ragna','HGH1600',
                'Tepos_10','Tepos_14','Tepos_35',
                'Tepos_37','ParatyphiC-RKS4594','TyphiTy2')

filt3xmat_ptc <- filt3xmat[rev(id_ord_ptc),spi_ord]

# plot heatmap
pheatmap((filt3xmat_ptc),color=viridis::viridis(100), cluster_rows = FALSE, 
         cluster_cols = FALSE, fontsize_row = 10,fontsize_col = 10)

#### pSPCV ####
pSPCV <- fread('pSPCV_id_pc_cov_edit_dist.csv') 
colnames(pSPCV) <- c("ID","pc_cov","edit_dist")
pSPCV <- pSPCV %>% mutate(cov_by_dist = pc_cov*edit_dist)
# actually, just stick to pc_cov, makes more sense 
tmp <- data.frame(pSPCV) %>% select(ID,pc_cov)
# need to filter for samples in spi one
# 3X min first
tmp <- tmp %>% filter(ID %in% c("Schwarzengrund-CVM19633","BareillyCFSAN000189","Bovismorbificans3114",
                                "EnteritidisP125109","GRY004",
                                'SME005','SJL020','SJL019','IV3002','IKI003','BOY008',
                                'S1L002','HGC040','HGC004','KKN099','AKY001','KPI001','GRY001','H1I004',
                                'MAJ022','SUA004','KO1037','SAP004','HO1003','NEP019','NEP021','NEP018',
                                'CHL003','XBQM20','KNC181','KNC056','KNC095','BPN005','KNC041','XBQM90',
                                'CPA002','SIA006','TBS012','ETR001','BRC034','BRC017',
                                'MGL011','CholeraesuisSC-B67','KNC139',
                                'TGP001','KSZ005','KNL026','MGL008','HDL004',
                                'GTH003','TAV007','KNL019','Ragna','HGH1600',
                                'Tepos_10','Tepos_14','Tepos_35',
                                'Tepos_37','ParatyphiC-RKS4594','TyphiTy2'))

rownames(tmp) <- tmp$ID
tmp$ID <- NULL
# order
tmp <- tmp[rev(id_ord_ptc),]
tmp[is.na(tmp)] <- 0 
names(tmp) <- rev(id_ord_ptc)
pheatmap(as.matrix(tmp),color=viridis::viridis(100), 
         cluster_rows = FALSE, cluster_cols = FALSE, fontsize_row = 10) 


#### SPI genes ####
# dataset of genes overlapping SPI loci (get this by intersecting SPI locus bed file and Typhi CT18 gff)
genetab <- 'SPI_genes_presence.tab'
spi_genes <- fread(genetab)
colnames(spi_genes) <- c("chr","start","end","gene","n_reads_overlap","n_bases_overlap",
                         "length","pc_covered","sample_id")
# subset to SPI7
spi_genes <- spi_genes[grepl("SPI-7",spi_genes$gene),]
spi_genes<- spi_genes %>% unique()
spi_genes <- merge(spi_genes, cov, all.x=TRUE)
spi_genes[is.na(cov)]$cov <- 100 # modern
spi_genes <- spi_genes %>% filter(cov >2) %>% unique()
spi_genesmat <- reshape2::acast(spi_genes, sample_id ~ gene, value.var = 'pc_covered')
