#### other SPI6-7 variable genes of interest ####
gene_subset <- 'SPI6-7_targeted_loci.tab'
spi67 <- fread(gene_subset)
spi67 <- unique(spi67)
colnames(spi67) <- c("chr","start","end","gene","n_reads_overlap","n_bases_overlap",
                     "length","pc_covered","sample_id")

spi67 <- merge(spi67, cov, all.x=TRUE)
spi67[is.na(cov)]$cov <- 100 # modern
spi67 <- spi67 %>% filter(cov >3) %>% unique()
spi67mat <- reshape2::acast(spi67, sample_id ~ gene, value.var = 'pc_covered')
spi67mat_indfilt <- spi67mat[rev(id_ord_ptc),]                  

pheatmap(spi67mat_indfilt,color=viridis::viridis(100), cluster_rows = FALSE,cluster_cols = FALSE)

#### pilin sequence variation ####
# additional required libraries 
library(ggtree) # tree plots
library(ape) # for pilin sequence variation
library(phytools) # for pilin sequence variation


# third component - pilin sequence variation 
aln <- 'pilin_locus.mind25.clustal_aln.fa'
pil_loc <- read.FASTA(aln)
# sanity check
base.freq(pil_loc, all=TRUE) # there are some gaps & some ns
# calculate distance
dist <- dist.dna(pil_loc, pairwise.deletion = T)
distN <- dist.dna(pil_loc, pairwise.deletion = T,model="N")
pheatmap::pheatmap(as.matrix(dist))
pheatmap::pheatmap(as.matrix(distN), color = rev(viridis::viridis(15)))
tr <- bionj(dist)
trN <- bionj(distN)
plot(tr)
plot(trN)

# midpoint root tree
tr_mid<- midpoint_root(tr)
tr_midN<- midpoint_root(trN)
plot(tr_midN)
plot(tr_mid)

options(ignore.negative.edge=TRUE)
ggtree(tr, layout="daylight") + theme_tree() + geom_tiplab()
ggtree(tr, layout="equal_angle") + theme_tree() + geom_tiplab()

ggtree(tr_mid)+ theme_tree2() + 
  geom_tiplab()

tr_mid_boots <- boot.phylo(tr_mid, 
           as.matrix(pil_loc), 
           FUN =function(xx) bionj(dist.dna(xx)), B=100,
           block=3)

summary(tr_mid_boots)
iqtree <- 'pilin_locus.mind25.clustal_aln.iqtree.treefile'
ml_tr <- read.tree(iqtree)
midpoint.root(ml_tr)
ml_tr
ggtree(ml_tr, layout="daylight") + theme_tree() + geom_tiplab()
## additional sanity checks 
library(phangorn)
pilin <- phangorn::read.phyDat(pil_loc, format="fasta")
dm <- dist.ml(pilin)
treeNJ  <- NJ(dm)
plot(midpoint.root(treeNJ))
plot(treeNJ,"unrooted")
fun <- function(x) midpoint.root(NJ(dist.ml(x)))
bs_nj <- bootstrap.phyDat(pilin,  fun)
plotBS( midpoint.root(treeNJ), bs_nj, main="NJ")

ggtree(midpoint.root(treeNJ))+ theme_tree2() + 
  geom_tiplab()  


ggtree(midpoint.root(ml_tr), size=1.5)+ theme_tree() + 
  geom_tiplab(size=5) + 
  geom_nodelab(geom="label", size=5)
